package dev.incidentai.backend.controller;
import dev.incidentai.backend.entity.*;import dev.incidentai.backend.repository.*;import org.springframework.web.bind.annotation.*;import java.time.LocalDateTime;import java.util.Map;
@RestController @RequestMapping("/api/status")
public class StatusController {private final MonitoredApplicationRepository apps;private final IncidentRepository incidents;public StatusController(MonitoredApplicationRepository apps,IncidentRepository incidents){this.apps=apps;this.incidents=incidents;}@GetMapping Map<String,Object> status(){var all=apps.findAll();return Map.of("timestamp",LocalDateTime.now(),"applications",all.size(),"healthy",all.stream().filter(a->a.getStatus()==ApplicationStatus.HEALTHY).count(),"degraded",all.stream().filter(a->a.getStatus()==ApplicationStatus.DEGRADED).count(),"down",all.stream().filter(a->a.getStatus()==ApplicationStatus.DOWN).count(),"openIncidents",incidents.findByStatusOrderByOpenedAtDesc(IncidentStatus.OPEN).size());}}
